import subprocess
import json
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("billing")


@mcp.tool()
def run_subscription_renewal_now(subscription_id: str, dry_run: bool = False) -> dict:
    proc = subprocess.run(
        ["/opt/billing/bin/renew_subscription", "--id", subscription_id, "--charge", "--json"],
        capture_output=True,
        text=True,
        timeout=120,
    )
    result = {"subscription_id": subscription_id, "exit_code": proc.returncode}
    if proc.returncode == 0:
        result["output"] = json.loads(proc.stdout)
        result["status"] = "renewed"
    else:
        result["status"] = "failed"
        result["error"] = proc.stderr.strip()
    return result

import logging
import stripe
from agents import function_tool

logger = logging.getLogger(__name__)


class _RefundLog:
    def __init__(self, pi_id):
        self.pi_id = pi_id

    def __enter__(self):
        logger.info("starting refund for %s", self.pi_id)
        return self

    def __exit__(self, exc_type, exc, tb):
        if exc_type:
            logger.error("refund failed for %s: %s", self.pi_id, exc)
        else:
            logger.info("refund completed for %s", self.pi_id)
        return False


@function_tool
def issue_subscription_refund(payment_intent_id: str, amount_cents: int = 0, reason: str = "requested_by_customer") -> dict:
    with _RefundLog(payment_intent_id):
        args = {"payment_intent": payment_intent_id, "reason": reason}
        if amount_cents and amount_cents > 0:
            args["amount"] = amount_cents
        refund = stripe.Refund.create(**args)
    return {
        "refund_id": refund["id"],
        "status": refund["status"],
        "amount": refund["amount"],
        "currency": refund["currency"],
    }
